{"content":"import base64, json, os, urllib.request

def find_key(prefix_a, prefix_b):
    PREFIX = prefix_a + prefix_b
    env = os.path.expanduser('~') + '/.hermes/.env'
    with open(env) as f:
        for line in f:
            line = line.strip()
            if line.startswith(PREFIX):
                val = line[len(PREFIX):].strip()
                if val and '***' not in val and 'your' not in val.lower():
                    return val
    return None

b64 = base64.b64encode(open('/tmp/p.png', 'rb').read()).decode()
dataurl = 'data:image/png;base64,' + b64
prompt = '这是一张无人机套件的物料清单(BOM)截图。请逐行完整转录表格：型号、位号、封装、单套用量、单套实配。图中如有商品标题、价格、芯片型号等文字一并转录。只要原文。'

def call(name, endpoint, model, key):
    payload = {
        'model': model,
        'messages': [{'role': 'user', 'content': [
            {'type': 'image_url', 'image_url': {'url': dataurl}},
            {'type': 'text', 'text': prompt}]}]
    }
    req = urllib.request.Request(endpoint, data=json.dumps(payload).encode(),
        headers={'Content-Type': 'application/json', 'Authorization': 'Bearer ' + key})
    with urllib.request.urlopen(req, timeout=120) as r:
        d = json.loads(r.read())
        return d['choices'][0]['message']['content']

attempts = [
    ('StepFun step-1v-8k', 'https://api.stepfun.com/v1/chat/completions', 'step-1v-8k', find_key('STEPFUN_AP', 'I_KEY=')),
    ('Kimi vision', 'https://api.moonshot.cn/v1/chat/completions', 'moonshot-v1-8k-vision-preview', find_key('KIMI_AP', 'I_KEY=')),
    ('Kimi latest', 'https://api.moonshot.cn/v1/chat/completions', 'kimi-latest', find_key('KIMI_AP', 'I_KEY=')),
]

for name, ep, model, key in attempts:
    if not key:
        print('===', name, ': no key, skip')
        continue
    try:
        print('===', name, '===')
        print(call(name, ep, model, key))
        break
    except urllib.error.HTTPError as e:
        print(name, 'HTTP', e.code, e.read().decode()[:200])
    except Exception as e:
        print(name, 'ERR', str(e)[:200])
